import { useEffect, useRef, useState, type CSSProperties } from "react";
import * as Tabs from "@radix-ui/react-tabs";
import { ArrowDownToLine, ArrowRight, ArrowUpRight, BarChart3, ChevronDown, Clock3, Database, FileText, Info, LoaderCircle, Maximize2, Minimize2, Minus, Network, Play, Plus, Radar, Search, ShieldAlert, Sparkles, X } from "lucide-react";
import { Badge, IconButton, downloadText } from "../../frontend/primitives";
import { replayRules, scenarios, situations, type EvidenceRow, type PreviewSituation } from "./fixtures";

export type BoardView = "situation" | "tools" | "evidence" | "graph";
export type PreviewState = "results" | "idle" | "loading" | "empty" | "error";

export function Scanner({ selected, onSelect, onInvestigate, state, onStateChange }: { selected: PreviewSituation; onSelect: (situation: PreviewSituation) => void; onInvestigate: (situation: PreviewSituation) => void; state: PreviewState; onStateChange: (state: PreviewState) => void }) {
  const [scenario, setScenario] = useState("credentials");
  const [start, setStart] = useState<string>(scenarios[0].start);
  const [end, setEnd] = useState<string>(scenarios[0].end);
  const [error, setError] = useState("");
  const [appliedWindow, setAppliedWindow] = useState({ start, end });
  const [appliedScenario, setAppliedScenario] = useState("credentials");
  const timer = useRef<ReturnType<typeof setTimeout> | null>(null);
  useEffect(() => () => { if (timer.current) clearTimeout(timer.current); }, []);
  const results = state === "results" ? (appliedScenario === "dns" ? situations.slice(1) : situations) : [];
  function run() {
    if (!start || !end || end <= start) { setError("Window end must be after window start."); return; }
    setError("");
    setAppliedWindow({ start, end });
    setAppliedScenario(scenario);
    onStateChange("loading");
    if (timer.current) clearTimeout(timer.current);
    timer.current = setTimeout(() => {
      onStateChange(scenario === "quiet" ? "empty" : "results");
      if (scenario !== "quiet") onSelect(scenario === "dns" ? situations[1] : situations[0]);
    }, 650);
  }
  const ruleRows = replayRules.map(rule => ({ ...rule, hit: state === "results" && rule.hit && (appliedScenario !== "dns" || rule.id === "fixture.dns") }));
  return <section className="rv-column rv-scanner" aria-label="Security review scanner">
    <div className="rv-panel-title"><Radar size={16} /><h1>Situation scanner</h1><span className="azs-mono">01</span></div>
    <form className="rv-scan-form" onSubmit={event => { event.preventDefault(); run(); }} noValidate>
      <label className="azs-field">Scenario<select aria-label="Test Scenarios" value={scenario} disabled={state === "loading"} onChange={event => { const next = scenarios.find(item => item.id === event.target.value)!; setScenario(next.id); setStart(next.start); setEnd(next.end); setError(""); }}>{scenarios.map(item => <option key={item.id} value={item.id}>{item.name}</option>)}</select></label>
      <div className="rv-date-fields"><label className="azs-field">Start / UTC<input type="datetime-local" aria-label="Scan start UTC" value={start} onChange={event => setStart(event.target.value)} disabled={state === "loading"} /></label><label className="azs-field">End / UTC<input type="datetime-local" aria-label="Scan end UTC" value={end} onChange={event => setEnd(event.target.value)} disabled={state === "loading"} /></label></div>
      <button className="azs-button rv-scan-button" type="submit" disabled={state === "loading"}>{state === "loading" ? <LoaderCircle size={14} className="azs-spin" /> : <Play size={13} fill="currentColor" />}{state === "loading" ? "Replaying fixture..." : "Scan ADX window"}</button>
      <span className="rv-fixture-note">Fixture replay / no ADX request</span>
      {error && <p className="azs-field-error" role="alert">{error}</p>}
    </form>
    {state !== "idle" && <details className="rv-fold rv-rules"><summary><ChevronDown size={14} /><strong>Rule execution</strong><span>{state === "loading" ? "replaying" : `${ruleRows.filter(rule => rule.hit).length} hit / ${ruleRows.filter(rule => !rule.hit).length} miss`}</span></summary>{ruleRows.map(rule => <details className="rv-rule-detail" key={rule.id}><summary className="rv-rule-item"><span className={`rv-rule-dot ${rule.hit ? "rv-rule-hit" : ""}`} /><span>{rule.label}</span><span className={`rv-rule-status ${rule.hit ? "rv-success" : ""}`}>{state === "loading" ? "pending" : rule.hit ? "hit" : "miss"}</span><span className="azs-mono">{rule.hit ? rule.count : 0}</span></summary><p>{rule.id} / fixed preview result. No query or threshold was evaluated.</p></details>)}</details>}
    {state === "results" && <><div className="rv-scanned-window"><span className="azs-eyebrow">SCANNED UTC INTERVAL</span><span>{appliedWindow.start.replace("T", " ")}<ArrowRight size={12} />{appliedWindow.end.slice(11)}</span></div><div className="rv-count-strip"><span><strong>{results.length}</strong> situations</span><span><strong>{results.filter(item => item.severity === "high").length}</strong> high</span><span className="azs-mono">SYNTHETIC</span></div><div className="rv-situations">{results.map(situation => <article key={situation.id} className={`rv-situation ${selected.id === situation.id ? "rv-selected" : ""}`}><button type="button" className="rv-situation-title" aria-label={`Select situation ${situation.host}`} aria-pressed={selected.id === situation.id} onClick={() => onSelect(situation)}><ShieldAlert size={16} /><span className="rv-situation-identity"><strong>{situation.host}</strong><small>{situation.principal}</small></span><span className={`rv-severity rv-severity-${situation.severity}`}>{situation.severity}</span></button><div className="rv-situation-meta">{situation.patterns.length} rules qualified / {situation.confidence} confidence</div>{selected.id === situation.id && <div className="rv-factors"><div className="rv-factor-heading"><span>Rule</span><span>Score</span><span>Events</span></div>{situation.patterns.map(pattern => <details key={pattern.id}><summary><span><strong>{pattern.label}</strong><small>{pattern.role}</small></span><span>+{pattern.score}</span><span>{pattern.count}</span></summary><p>{pattern.observation}</p></details>)}</div>}<button className="azs-button azs-button-ghost rv-investigate-button" onClick={() => onInvestigate(situation)}>Investigate with Review agent<ArrowUpRight size={14} /></button></article>)}</div></>}
    {state === "idle" && <Empty icon="scan" title="Scanner idle" detail="No fixture window has been replayed." />}
    {state === "empty" && <Empty icon="scan" title="No qualifying situations" detail="The quiet-interval fixture contains no rule hits. This is not a safety assessment." />}
    {state === "loading" && <div className="rv-loading-state" role="status"><LoaderCircle size={18} className="azs-spin" /><span>Replaying the selected fixture...</span><div className="rv-skeleton" /><div className="rv-skeleton" /></div>}
    {state === "error" && <div className="rv-local-error" role="alert"><Info size={17} /><h2>Replay unavailable</h2><p>Simulated fixture error. No source data has changed.</p><button className="azs-button azs-button-secondary" onClick={run}>Retry fixture</button></div>}
  </section>;
}

export function Empty({ title, detail, icon = "data" }: { title: string; detail: string; icon?: "data" | "scan" }) {
  return <div className="rv-empty">{icon === "scan" ? <Radar size={28} /> : <Database size={28} />}<h2>{title}</h2><p>{detail}</p></div>;
}

export function EvidenceTable({ rows, label = "Cited evidence" }: { rows: EvidenceRow[]; label?: string }) {
  const [query, setQuery] = useState("");
  const [open, setOpen] = useState("");
  const visible = rows.filter(row => Object.values(row).join(" ").toLowerCase().includes(query.toLowerCase()));
  return <div className="rv-evidence-table"><div className="rv-evidence-toolbar"><div className="azs-input-icon"><Search size={14} /><input type="search" aria-label={`Search ${label.toLowerCase()}`} placeholder="Search records..." value={query} onChange={event => setQuery(event.target.value)} /></div><IconButton label={`Download ${label.toLowerCase()}`} onClick={() => downloadText("security-review-synthetic-evidence.json", JSON.stringify(visible, null, 2), "application/json")}><ArrowDownToLine size={16} /></IconButton></div><table><caption className="azs-sr-only">{label} / synthetic fixtures</caption><thead><tr><th>UTC</th><th>Event</th><th>Source</th></tr></thead><tbody>{visible.map(row => <tr key={row.id}><td className="azs-mono">{row.time}</td><td><button className="rv-evidence-link" aria-expanded={open === row.id} onClick={() => setOpen(open === row.id ? "" : row.id)}>{row.event}<ArrowUpRight size={11} /></button><span className="rv-id">{row.id}</span></td><td>{row.product}</td></tr>)}</tbody></table>{!visible.length && <div className="rv-empty rv-empty-small"><p>No matching records</p><button className="azs-button azs-button-secondary" onClick={() => setQuery("")}>Clear record search</button></div>}{open && rows.some(row => row.id === open) && <div className="rv-evidence-inspect"><div className="rv-subheading"><strong className="azs-mono">{open}</strong><IconButton label="Close evidence record" onClick={() => setOpen("")}><X size={14} /></IconButton></div><p>{rows.find(row => row.id === open)!.detail}</p><span className="rv-fixture-note">Source: local synthetic fixture / not retrieved from ADX</span></div>}<div className="rv-evidence-foot"><span>{visible.length} rows</span><span className="azs-mono">resource_id / stable identity</span></div></div>;
}

const toolSpecs = [{ id: "timeline", label: "Situation timeline", icon: Clock3 }, { id: "products", label: "Product composition", icon: Database }, { id: "auth", label: "Authentication mix", icon: BarChart3 }, { id: "egress", label: "Firewall baseline", icon: Network }];

export function ToolBoard({ selected, state, view, onViewChange, onAsk, expanded, onExpandedChange }: { selected: PreviewSituation; state: PreviewState; view: BoardView; onViewChange: (view: BoardView) => void; onAsk: (message: string) => void; expanded: boolean; onExpandedChange: () => void }) {
  const [picked, setPicked] = useState<string[]>([]);
  const [tool, setTool] = useState("timeline");
  const [graphNode, setGraphNode] = useState("");
  const [zoom, setZoom] = useState(100);
  const current = state === "results";
  function pick(value: string) { setPicked(previous => previous.includes(value) ? previous : [...previous, value]); }
  const ids = [...new Set([selected.host, selected.principal, "archive-01", "archive.example.test"])];
  const focused = graphNode && ids.includes(graphNode) ? graphNode : selected.host;
  return <section className={`rv-column rv-board ${expanded ? "rv-expanded" : ""}`} aria-label="Central tool board"><Tabs.Root value={view} onValueChange={value => onViewChange(value as BoardView)} className="rv-board-shell"><div className="rv-board-top"><Tabs.List className="rv-board-tabs" aria-label="Tool board views">{["situation", "tools", "evidence", "graph"].map(tab => <Tabs.Trigger key={tab} value={tab}>{tab}</Tabs.Trigger>)}</Tabs.List><IconButton label={expanded ? "Restore tool board" : "Expand tool board"} onClick={onExpandedChange}>{expanded ? <Minimize2 size={16} /> : <Maximize2 size={16} />}</IconButton></div>
    <Tabs.Content value="situation" className="rv-board-content">{current ? <>
      <details className="rv-board-fold rv-summary" open><summary><ChevronDown size={14} /><h2>Situation summary</h2><span className="rv-small-tag">Fixture</span></summary><p>{selected.summary}</p></details>
      <div className="rv-selected-heading"><span className="azs-eyebrow">SELECTED SITUATION</span><div><button onClick={() => pick(selected.host)} className="rv-host-button">{selected.host}</button><span className={`rv-severity rv-severity-${selected.severity}`}>{selected.severity}</span></div><button onClick={() => pick(selected.principal)} className="rv-principal-button">{selected.principal}<Plus size={11} /></button></div>
      <details className="rv-board-fold rv-diagnosis" open><summary><ChevronDown size={14} /><h2>Review agent investigation</h2><span className="rv-small-tag">Needs review</span></summary><h3>{selected.headline}</h3><p>{selected.narrative}</p><details className="rv-reasoning"><summary>What it rests on and what would change it<ChevronDown size={13} /></summary><strong>Supporting observations</strong><ul>{selected.patterns.map(pattern => <li key={pattern.id}>{pattern.observation}</li>)}</ul><strong>Would change the call</strong><p>{selected.alternative}</p><p className="rv-fixture-note">Fixture interpretation / no model or knowledge retrieval</p></details><div className="rv-diagnosis-actions"><button onClick={() => onAsk(`Examine alternatives for ${selected.host}.`)}><Sparkles size={12} />Take it further in chat</button><button onClick={() => onAsk(`Review the evidence for ${selected.host}.`)}><ArrowUpRight size={12} />Investigate again</button></div></details>
      <details className="rv-board-fold rv-sequence" open><summary><ChevronDown size={14} /><h2>Sequence of events</h2><span className="rv-small-tag">{selected.steps.length} steps</span></summary><ol>{selected.steps.map((step, index) => <li key={step.time}><span className="rv-step-number">{String(index + 1).padStart(2, "0")}</span><details><summary><time>{step.time} UTC</time><ChevronDown size={12} /></summary><div className="rv-step-evidence">{step.evidence.map(id => <button key={id} onClick={() => onViewChange("evidence")}><FileText size={12} />{id}</button>)}<span>Synthetic record references</span></div></details><p>{step.description}</p></li>)}</ol></details>
      <div className="rv-metrics"><details><summary><strong>{selected.patterns.length}</strong><span>correlated patterns</span><Info size={11} /></summary><p>Number of fixture patterns attached to this situation.</p></details><details><summary><strong>{selected.evidence.length}</strong><span>evidence records</span><Info size={11} /></summary><p>Count of unique synthetic evidence IDs shown in the Evidence tab.</p></details><details><summary><strong>{selected.confidence}</strong><span>confidence</span><Info size={11} /></summary><p>Fixture category, not a measured probability.</p></details></div>
      <div className="rv-boundary"><Info size={14} /><p>Historical replay. Observed records and interpretation stay separate. No live monitoring or response actions.</p></div>
    </> : <Empty title={state === "loading" ? "Preparing fixture" : "No situation selected"} detail={state === "empty" ? "No registered fixture qualified in this interval." : "Choose a replay window in the scanner."} />}</Tabs.Content>
    <Tabs.Content value="tools" className="rv-board-content"><div className="rv-subheading"><h2>Investigation tools</h2><span className="rv-small-tag">Fixture outputs</span></div><div className="rv-tool-grid">{toolSpecs.map(({ id, label, icon: Symbol }) => <button key={id} aria-pressed={tool === id} onClick={() => setTool(id)}><Symbol size={18} /><span><strong>{label}</strong><small>Open sample result</small></span><ArrowUpRight size={13} /></button>)}</div><div className="rv-tool-result"><div className="rv-subheading"><h2>{toolSpecs.find(item => item.id === tool)!.label}</h2><Badge tone="info">Synthetic</Badge></div>{tool === "timeline" ? <div className="rv-mini-timeline">{selected.steps.map((step, index) => <div key={step.time}><span className="azs-mono">{step.time}</span><span className="rv-timeline-bar" style={{ width: `${25 + index * 17}%` }} /><strong>{step.evidence.length}</strong></div>)}</div> : tool === "egress" ? <Empty title="No firewall fixture" detail="A missing baseline does not establish normal or abnormal activity." /> : <table className="rv-compact-table"><thead><tr><th>{tool === "auth" ? "Event ID" : "Product"}</th><th>Records</th></tr></thead><tbody>{Object.entries(selected.evidence.reduce<Record<string, number>>((total, row) => { const key = tool === "auth" ? row.eventId : row.product; total[key] = (total[key] || 0) + 1; return total; }, {})).map(([key, value]) => <tr key={key}><td>{key}</td><td>{value}</td></tr>)}</tbody></table>}<span className="rv-fixture-note">Local fixture output / no query executed</span></div><button className="azs-button azs-button-ghost rv-full-command" onClick={() => onAsk("Which evidence best explains the selected situation?")}>Let the agent choose a tool<ArrowRight size={14} /></button></Tabs.Content>
    <Tabs.Content value="evidence" className="rv-board-content"><div className="rv-subheading"><h2>Cited evidence</h2><span className="rv-small-tag">{current ? selected.evidence.length : 0} records</span></div>{current ? <EvidenceTable key={selected.id} rows={selected.evidence} /> : <Empty title="No evidence context" detail="Select a situation first." />}</Tabs.Content>
    <Tabs.Content value="graph" className="rv-board-content"><div className="rv-subheading"><h2>Entity graph</h2><span className="rv-small-tag">Fixed fixture</span></div><div className="rv-graph-toolbar"><span>Depth 1 / {ids.length} entities</span><div><IconButton label="Zoom out graph" disabled={zoom <= 80} onClick={() => setZoom(value => Math.max(80, value - 10))}><Minus size={14} /></IconButton><span className="azs-mono">{zoom}%</span><IconButton label="Zoom in graph" disabled={zoom >= 120} onClick={() => setZoom(value => Math.min(120, value + 10))}><Plus size={14} /></IconButton></div></div><div className="rv-entity-graph"><div className="rv-graph-content" style={{ transform: `scale(${zoom / 100})` } as CSSProperties}><svg viewBox="0 0 400 280" preserveAspectRatio="none" aria-hidden="true"><path d="M90 75 L295 65 L300 215 L85 210 Z M90 75 L300 215" fill="none" stroke="var(--azs-control)" strokeWidth="1.3" strokeDasharray="4 5" /></svg>{ids.map((name, index) => <button key={name} className={`rv-entity-node rv-node-${index}`} aria-pressed={focused === name} onClick={() => { setGraphNode(name); pick(name); }}><span>{index === 1 ? <ShieldAlert size={18} /> : index === 3 ? <Network size={18} /> : <Database size={18} />}</span><strong>{name}</strong><small>{index === 1 ? "Principal" : index === 3 ? "Domain" : "Host"}</small></button>)}</div></div><dl className="rv-graph-detail"><div><dt>Selected entity</dt><dd>{focused}</dd></div><div><dt>Provenance</dt><dd>Synthetic topology, not inferred relationships</dd></div></dl></Tabs.Content>
  </Tabs.Root><div className="rv-entity-tray"><span className="rv-tray-label"><Network size={13} />Entity selection</span>{picked.length ? <><div className="rv-picked-list">{picked.map(name => <span key={name}>{name}<button aria-label={`Remove entity ${name}`} onClick={() => setPicked(current => current.filter(value => value !== name))}><X size={11} /></button></span>)}</div><button className="azs-button azs-button-secondary" onClick={() => { setGraphNode(picked[0]); onViewChange("graph"); }}>Visualize<ArrowUpRight size={12} /></button></> : <span className="rv-fixture-note">None selected</span>}</div></section>;
}